    UNION ALL SELECT 'CELL_TYPE_81' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'CELL_TYPE_82' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'CITY_MST' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'COUNTRY_MST' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'CURRENCY_LIST' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'CUST_GROUP' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'CUST_GROUP_DTL' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'Company' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'CompanyIdInternalTxn' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'DMF0005_DM_CONTRIBUTION_TYPE_CD' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'DMF0005_DM_OS_CORP_CD' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'DMF0005_REPORT_GROUP1' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'DMF0005_REPORT_GROUP2' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'DMF0005_REPORT_GROUP3' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'DMF0005_REPORT_GROUP4' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'DMF0005_REPORT_GROUP5' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'DMF0005_REPORT_GROUP6' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'DMF0005_REPORT_GROUP7' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'DMF0005_REPORT_GROUP8' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'END_CUST_REPORT' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'EndCustomer' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'EndCustomerByDivisionDept' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'Incoterms' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'ItemType' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'PRODUCTION_PROCESS' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'ROUTE' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'SCM0001_GET_DIVISION' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'SOLD_TO_CUST_REPORT' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'SYSTEM' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'SalesCompany' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'SalesPlant' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'ScmSitebyEndCustomer40' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'SiteByEndCustomer' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'SoldCustomer' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'TeambyDivision' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'TeambyDivision2' SQL_ID, 'DM' MDU_DIVS_CD FROM DUAL
    UNION ALL SELECT 'YesOrNo' SQL_ID, 'ALL' MDU_DIVS_CD FROM DUAL) S;

/* 5) 클라우드에만 있는 화면 META 행(사내에 없음) — 참고. 지우지 않음 */
SELECT 'SCM_ADM_API_M' AS TBL, T.API_ID
  FROM SCM_MGR.SCM_ADM_API_M T
 WHERE (API_ID LIKE 'DMF0008' || '\_%' ESCAPE '\')
   AND NOT EXISTS (SELECT 1 FROM (SELECT CAST(NULL AS VARCHAR2(4000)) API_ID FROM DUAL WHERE 1 = 0) S WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~'));
SELECT 'SCM_ADM_MNU_BTN_MPG_M' AS TBL, T.MNU_ID, T.SHT_NM, T.MNU_BTN_CD
  FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T
 WHERE (MNU_ID = 'DMF0008')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'DMF0008' MNU_ID, 'division' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'main' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'main' SHT_NM, 'STATUS_UPDATE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'project' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'project' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'project' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'repair' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'repair' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'repair' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'salesSite' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'salesSite' SHT_NM, 'INSERT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'salesSite' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'salesSite' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'site' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'sspm' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'sspm' SHT_NM, 'INSERT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'sspm' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'sspm' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'summary' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0008' MNU_ID, 'updateHistory' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL) S WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~'));
